head.script:
scwin.onpageload = function() {
	var html = '<div>네이버</div>';
	html += '<a href="https://kstaplus.ksnet.co.kr" target="_blank">바로가기기</a>';
	editor1.setHTML(html);
};
scwin.trigger1_onclick = function(e) {
	editor1.setDisabled(true);
};
scwin.trigger2_onclick = function(e) {
	editor1.setDisabled(false);
};
scwin.checkVal = function() {
	let elements = (document.getElementById('editor1_disabled_div') || document.getElementById('mf_editor1_disabled_div'));
	return elements !== null;
};
